// =============================================================
// Filtra LOG_TAREFAS e monta mensagens por prestador
// - Janela: data_checkout === amanhã (D+1 apenas)
// - status_tarefa === 'reservado'
// - Agrupa por equipe_id (telefone)
// - Ordena tarefas cronologicamente
// - Gera 1 item por mensagem (prestador + gerentes + cópia se houver)
// - Cabeçalho personalizado com nome do prestador (lookup em CAD_UNIDADES)
// =============================================================

var config = $('Set: Config').first().json;
var GERENTE1 = String(config.gerente1_telefone || '').trim();
var GERENTE2 = String(config.gerente2_telefone || '').trim();

var ROTAS_COPIA = {};
try {
  ROTAS_COPIA = JSON.parse(config.rotas_copia_json || '{}');
} catch (e) {
  ROTAS_COPIA = {};
}

// === Mapa de nomes dos prestadores (a partir do CAD) ===
var MAPA_NOMES = {};
var cadRows = $('Sheets: Ler CAD1').all().map(function(i) { return i.json; });
for (var i = 0; i < cadRows.length; i++) {
  var eid = String(cadRows[i].equipe_id || '').trim();
  if (eid && !MAPA_NOMES[eid]) {
    MAPA_NOMES[eid] = String(cadRows[i].equipe_nome || '').trim();
  }
}

var rows = $('Sheets: Ler LOG1').all().map(function(i) { return i.json; });

// === Janela de datas: apenas D+1 ===
var hoje = new Date();
hoje.setHours(0, 0, 0, 0);

var amanha = new Date(hoje);
amanha.setDate(amanha.getDate() + 1);

function pad2(n) { return n < 10 ? '0' + n : '' + n; }
function isoLocal(d) {
  return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
}

var amanhaStr = isoLocal(amanha);

// === Helpers ===
function norm(d) { return String(d || '').slice(0, 10); }

function getAtencao(r) {
  if (r['atenção'] !== undefined && r['atenção'] !== null) return r['atenção'];
  if (r['atencao'] !== undefined && r['atencao'] !== null) return r['atencao'];
  return '';
}

function formatarDataCurta(iso) {
  var s = norm(iso);
  if (!s || s.length < 10) return s;
  return s.slice(8, 10) + '/' + s.slice(5, 7);
}

function diaSemanaAbrev(iso) {
  var dias = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
  var s = norm(iso);
  if (!s || s.length < 10) return '';
  var d = new Date(s + 'T12:00:00Z');
  if (isNaN(d.getTime())) return '';
  return dias[d.getUTCDay()] || '';
}

// === Filtrar elegíveis: apenas amanhã ===
var elegiveis = [];
for (var i2 = 0; i2 < rows.length; i2++) {
  var r = rows[i2];
  if (String(r.status_tarefa || '').toLowerCase() !== 'reservado') continue;
  if (!r.data_checkout) continue;
  if (!r.equipe_id) continue;

  var dataStr = norm(r.data_checkout);
  if (dataStr.length < 10) continue;
  if (dataStr !== amanhaStr) continue;

  elegiveis.push(r);
}

// === Agrupar por prestador ===
var porPrestador = {};
for (var j = 0; j < elegiveis.length; j++) {
  var t = elegiveis[j];
  var key = String(t.equipe_id).trim();
  if (!key) continue;
  if (!porPrestador[key]) porPrestador[key] = [];
  porPrestador[key].push(t);
}

// === Montar mensagens ===
var mensagens = [];
var prestadores = Object.keys(porPrestador);

for (var k = 0; k < prestadores.length; k++) {
  var prestador = prestadores[k];
  var tarefas = porPrestador[prestador];
  var nomePrestador = MAPA_NOMES[prestador] || '';

  tarefas.sort(function(a, b) {
    return norm(a.data_checkout).localeCompare(norm(b.data_checkout));
  });

  var temAtencao = false;
  for (var l = 0; l < tarefas.length; l++) {
    if (String(getAtencao(tarefas[l])).trim() !== '') {
      temAtencao = true;
      break;
    }
  }

  var cabecalho = nomePrestador
    ? '*AGENDA DE AMANHÃ — ' + nomePrestador + '*\n'
    : '*AGENDA DE AMANHÃ*\n';

  var texto = cabecalho;
  texto += 'Suas tarefas de limpeza para amanhã 🔔:\n';

  for (var m = 0; m < tarefas.length; m++) {
    var ta = tarefas[m];
    var marca = String(getAtencao(ta)).trim() !== '' ? ' ⚠️' : '';
    texto += '\n';
    texto += '🏠 Unidade: ' + (ta.unidade_nome || '') + marca + '\n';
    texto += '📅 Data: ' + formatarDataCurta(ta.data_checkout) + ' - ' + diaSemanaAbrev(ta.data_checkout) + '\n';
    texto += '⏱️ Horário: ' + (ta.hora_limpeza_agendada || '') + '\n';
  }

  if (temAtencao) {
    texto += '\nATENÇÃO ⚠️ Unidades com entrada e saída no mesmo dia são prioridades';
  }

  // 1. Prestador
  mensagens.push({ json: { numero: prestador, texto: texto, destinatario: 'prestador', equipe_id: prestador } });

  // 2. Gerente 1
  if (GERENTE1) mensagens.push({ json: { numero: GERENTE1, texto: texto, destinatario: 'gerente_1', equipe_id: prestador } });

  // 3. Gerente 2
  if (GERENTE2) mensagens.push({ json: { numero: GERENTE2, texto: texto, destinatario: 'gerente_2', equipe_id: prestador } });

  // 4. Cópia adicional roteada
  if (ROTAS_COPIA[prestador]) {
    mensagens.push({ json: { numero: ROTAS_COPIA[prestador], texto: texto, destinatario: 'copia_extra', equipe_id: prestador } });
  }
}

if (mensagens.length === 0) return [{ json: { vazio: true } }];
return mensagens;

var delay = Number($('Set: Config').first().json.delay_ms) || 5000;
await new Promise(function(r) { setTimeout(r, delay); });
return $input.all();
